namespace PurpleStream;
sealed partial class Main {
 static IEnumerable<Control> Descendants(Control root){foreach(Control child in root.Controls){yield return child;foreach(var nested in Descendants(child))yield return nested;}}
 public async Task UiChecks(){var report=new List<string>();void Stage(string line){report.Add(line);File.WriteAllLines(Path.Combine(AppContext.BaseDirectory,"ui-tests.txt"),report);}Stage("RUNNING: real control checks");try{SeedDemo();Stage("RUNNING: opening Movies");await ShowLibrary("Movies");Stage("RUNNING: Movies created");await Task.Delay(300);var tree=Descendants(body).OfType<TreeView>().Single();var india=tree.Nodes.Cast<TreeNode>().First(n=>n.Tag is DirectorySelection s&&s.Country=="IN");india.Expand();tree.SelectedNode=india;tree.SelectedNode=india.Nodes[0];await Task.Delay(1200);if(Descendants(body).OfType<ListView>().Single().VirtualListSize!=1)throw new Exception("Movie country/genre UI filtering failed: "+Descendants(body).OfType<LibraryBrowser>().Single().Diagnostics);await ShowLibrary("Series");await Task.Delay(250);if(!Descendants(body).OfType<TreeView>().Single().Nodes.Cast<TreeNode>().Any(n=>n.Tag is DirectorySelection s&&s.Country=="TR"))throw new Exception("Series country tree missing");Stage("PASS: real WinForms movie and series country/genre navigation and virtual title list.");
 if(!Descendants(player).OfType<Button>().Any(b=>b.Text=="+10s")||!Descendants(player).OfType<TrackBar>().Any(t=>t.Maximum==1000&&t.Height>0))throw new Exception("Player controls missing");player.Fullscreen();await Task.Delay(150);if(player.FindForm()?.FormBorderStyle!=FormBorderStyle.None)throw new Exception("Fullscreen did not open");player.Fullscreen();await Task.Delay(100);if(player.FindForm()!=this)throw new Exception("Fullscreen did not restore player");Stage("PASS: timeline/transport controls and fullscreen enter/exit restore the player.");
 Home();Stage("RUNNING: settings toolbar");bool opened=false;using(var closeDialog=new System.Windows.Forms.Timer{Interval=100}){closeDialog.Tick+=(_,_)=>{var settings=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Text=="Settings");if(settings!=null){opened=true;settings.Close();}};closeDialog.Start();var tool=Descendants(this).OfType<CircleTool>().Single(b=>b.AccessibleName=="Settings");Stage($"DIAGNOSTIC: visible={tool.Visible}, enabled={tool.Enabled}, selectable={tool.CanSelect}, formVisible={Visible}, formEnabled={Enabled}, parentVisible={tool.Parent?.Visible}");tool.Click+=(_,_)=>Stage("DIAGNOSTIC: click event dispatched");tool.PerformClick();closeDialog.Stop();}if(!opened)throw new Exception("Toolbar button did not invoke Settings");Stage("PASS: dashboard toolbar button opens its working settings dialog.");
 await Multiscreen();await Task.Delay(100);var multi=Application.OpenForms.OfType<MultiscreenWindow>().Single();if(Descendants(multi).OfType<Button>().Count(b=>b.Text=="Choose / Play")!=4)throw new Exception("Multiscreen slots missing");await multi.CheckControls(new Uri(Path.GetFullPath("work/v4-tests/seek.wav")).AbsoluteUri);await multi.Shutdown();multi.Close();Stage("PASS: first playback is muted before clicking, delayed startup and channel replacement preserve mute, first/second clicks match labels; four real native audio outputs are independently controlled; 2/3/4 screens, hidden-screen stop, selectable main screen and equal-layout restoration.");
 var pickerSettings=new Saved();pickerSettings.Favorites.Add(catalogs["Live TV"].Single(c=>c.Name=="PTV Sports HD").Url);pickerSettings.History.Add(new(catalogs["Live TV"].Single(c=>c.Name=="HUM TV"),0,DateTimeOffset.Now));using(var picker=new ChannelPicker(catalogs["Live TV"].Concat(Enumerable.Range(0,12000).Select(i=>new Channel("Fixture channel "+i,"https://fixture.invalid/large/"+i,"United Kingdom | Sports"))),pickerSettings)){picker.Show(this);await picker.CheckFilters();}Stage("PASS: real channel picker with 12,000 extra fixture channels: country/category navigation, combined search, favorites, recently watched, empty results and correct selection.");
 int heartbeats=0;using(var pulse=new System.Windows.Forms.Timer{Interval=50}){pulse.Tick+=(_,_)=>heartbeats++;pulse.Start();player.Engine.Play("http://192.0.2.1:9/unavailable",0);await Task.Delay(700);player.Stop();pulse.Stop();}if(heartbeats<5)throw new Exception("UI stopped responding while stream connected");Stage("PASS: UI timer kept ticking while an unavailable stream was connecting; Stop returned without blocking.");
 var fake=new Saved{Mode="Xtream Codes",Server="http://fixture.invalid",User="test",Secret=SettingsStore.Protect("fixture")};using(var service=new ProviderService(fake,new ProviderTransport(new OfflineFixture()))){await service.Authenticate(default);var live=await service.Catalog("Live TV",default);Channel? archive=null;using var guide=new GuideWindow(service,live,live[0],true,c=>archive=c);guide.Show(this);await guide.LoadGuide();var rows=Descendants(guide).OfType<ListView>().Single();if(rows.Items.Count!=1)throw new Exception("Guide UI missing programme");rows.Items[0].Selected=true;Descendants(guide).OfType<Button>().Single(b=>b.Text=="Play archive").PerformClick();if(archive?.Kind!="Catch-up")throw new Exception("Catch-up button did not produce archive playback");guide.Close();}Stage("PASS: provider EPG populates the guide UI and Catch-up action selects an archive stream.");
 File.WriteAllLines(Path.Combine(AppContext.BaseDirectory,"ui-tests.txt"),report);
 }catch(Exception e){report.Add("FAIL: "+e);File.WriteAllLines(Path.Combine(AppContext.BaseDirectory,"ui-tests.txt"),report);}finally{Close();}}
}








